import base64
from itertools import islice
import logging
import os
from typing import Callable, Iterable, TypeVar
from uuid import UUID

from flask import Request, Response, g

from argus.backend.models.web import User

T = TypeVar('T')

LOGGER = logging.getLogger(__name__)
FlaskView = Callable[..., Response]


def first(iterable, value, key: Callable = None, predicate: Callable = None):
    for elem in iterable:
        if predicate and predicate(elem, value):
            return elem
        elif key and key(elem) == value:
            return elem
        elif elem == value:
            return elem
    return None


def chunk(iterable: Iterable[T], slice_size=90) -> list[list[T]]:
    it = iter(iterable)
    return iter(lambda: list(islice(it, slice_size)), [])


def check_scheduled_test(test, group, testname):
    return testname in (f"{group}/{test}", test)


def strip_html_tags(text: str):
    return text.replace("<", "&lt;").replace(">", "&gt;")


def convert_str_list_to_uuid(lst: list[str]) -> list[UUID]:
    return [UUID(s) for s in lst]


def get_payload(client_request: Request) -> dict:
    if not client_request.is_json:
        raise Exception(
            "Content-Type mismatch, expected application/json, got:",
            client_request.content_type
        )
    request_payload = client_request.get_json()

    return request_payload


def current_user() -> User:
    return g.user


def gen_pass() -> str:
    return base64.encodebytes(os.urandom(48)).decode("ascii").strip()


def get_build_number(build_job_url: str) -> int | None:
    build_number = build_job_url.rstrip("/").split("/")[-1] if build_job_url else -1
    if build_number:
        try:
            return int(build_number)
        except ValueError:
            LOGGER.error("Error parsing build number from %s: got %s as build_number", build_job_url, build_number)
    return None


def check_version(filter_string: str, version: str) -> bool:
    if not version:
        return False
    if version.startswith(filter_string):
        return True

    return False
import os
import hashlib
from flask import (
    Blueprint, flash, g, redirect, render_template, request, session, url_for, current_app
)
from werkzeug.security import check_password_hash
from coodie.exceptions import DocumentNotFound

from argus.backend.error_handlers import handle_profile_exception
from argus.backend.models.web import User, UserRoles
from argus.backend.service.user import (
    UserService,
    UserServiceException,
    check_roles,
    load_logged_in_user,
    login_required,
)

bp = Blueprint('auth', __name__, url_prefix='/auth')
bp.register_error_handler(UserServiceException, handle_profile_exception)


@bp.route('/register', methods=('GET', 'POST'))
def register():
    return redirect(url_for("auth.login"))


@bp.route('/login', methods=('GET', 'POST'))
def login():
    if g.user:
        if redirect_target := session.pop("redirect_target", None):
            return redirect(redirect_target)
        return redirect(url_for("main.home"))

    token = hashlib.sha256((os.urandom(64))).hexdigest()
    session["csrf_token"] = token

    if request.method == 'POST':
        try:
            if "password" not in current_app.config.get("LOGIN_METHODS", []):
                raise UserServiceException("Password Login is disabled")
            username = request.form["username"]
            password = request.form["password"]

            try:
                user: User = User.get(username=username)
            except DocumentNotFound:
                raise UserServiceException("User not found")

            if not check_password_hash(user.password, password):
                raise UserServiceException("Incorrect Password")

            session.clear()
            session["user_id"] = str(user.id)
            session["csrf_token"] = token
        except UserServiceException as exc:
            flash(next(iter(exc.args), "No message"), category="error")

        return redirect(url_for('main.home'))

    return render_template('auth/login.html.j2',
                           csrf_token=token,
                           github_cid=current_app.config.get("GITHUB_CLIENT_ID", "NO_CLIENT_ID"),
                           github_scopes=current_app.config.get("GITHUB_SCOPES", "user:email read:user read:org")
                           )


@bp.route("/login/cf", methods=("POST",))
def cf_login():
    res = UserService().cf_login_or_register()
    if not res["redirect_optional"]:
        return redirect(url_for(res["redirect_to"]))
    if redirect_target := session.pop("redirect_target", None):
        return redirect(redirect_target)
    return redirect(url_for(res["redirect_to"]))


@bp.route("/profile/api/token/generate", methods=("POST",))
@login_required
def generate_api_token():
    new_token = UserService().generate_token(g.user)
    session["token_generated"] = new_token
    return redirect(url_for('main.profile'))


@bp.route('/admin/impersonate', methods=("POST","GET"))
@check_roles(UserRoles.Admin)
@login_required
def switch_user():

    if request.method == 'POST':
        try:
            user_id = request.form["user_id"]
        except KeyError:
            flash("No user id", category="error")
            return redirect(url_for('main.profile'))
        UserService().set_user_impersonation(user_id)
        return redirect(url_for('main.profile'))

    users = UserService().get_users_privileged(service_only=True)

    return render_template('auth/user_switch.html.j2', users=users)


@bp.route('/admin/impersonate/stop', methods=("POST",))
@login_required
def stop_impersonation():

    UserService().stop_user_impersonation()
    return redirect(url_for('main.profile'))



@bp.route('/logout', methods=("POST",))
def logout():
    session.clear()
    session["manual_logout"] = True
    return redirect(url_for('auth.login'))


bp.before_app_request(load_logged_in_user)

