    def send_notification(self, receiver: UUID, sender: UUID, notification_type: ArgusNotificationTypes, source_type: ArgusNotificationSourceTypes, source_id: UUID, title: str | None=None, content: str | None=None, content_params: dict | None=None) -> Any:
